import pytest

from bedrock_protocol import v1001, v2168, v2225

versions = [v1001, v2168, v2225]

# generated by gophertunnel b8bd735 and again at 6353c49:
# packet.ClientBoundDataDrivenUIReload{}
EMPTY = bytes.fromhex("")

GOLDENS = [
    pytest.param(v.ClientboundDataDrivenUIReloadPacket(), EMPTY, id=f"{v.__name__.rpartition('.')[2]}-empty")
    for v in versions
]


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_data_driven_ui_reload_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_clientbound_data_driven_ui_reload_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize("version", versions)
def test_clientbound_data_driven_ui_reload_rejects_trailing_bytes(version):
    with pytest.raises(ValueError, match="trailing bytes"):
        version.ClientboundDataDrivenUIReloadPacket.from_bytes(bytes.fromhex("ff7f01"))
